def generated_loss(batch, model_output, extra):
    adv_scaled = 1.0 / (1.0 + ops.exp(-batch['advantage_gap'] * 0.5))
    raw_margin = float(extra.get('alpha', 1.0)) * float(extra.get('scale', 0.75)) * (batch['log_prob_w'] - batch['log_prob_l'])
    combined_value = raw_margin * adv_scaled
    x = ops.clamp(combined_value, -20.0, 20.0)
    loss = -ops.logsigmoid(x)
    if batch.get('weight', None) is not None:
        loss = loss * batch['weight']
    return loss.mean()
